from manim import *


def _smart_text(text, font_size):
    """含非 ASCII 字符（中文/希腊字母/全角符号）用 Text（Pango 渲染，支持中文）；纯 ASCII 用 MathTex（LaTeX 渲染，支持数学公式）。"""
    return Text(text, font_size=font_size) if any(ord(c) > 127 for c in text) else MathTex(text, font_size=font_size)


# 安全的颜色名映射（避免对用户输入做 eval）
COLOR_MAP = {
    "red": RED, "blue": BLUE, "green": GREEN, "yellow": YELLOW,
    "orange": ORANGE, "purple": PURPLE, "pink": PINK, "white": WHITE,
    "black": BLACK, "cyan": TEAL, "gray": GREY_B, "grey": GREY_B,
}


class GeometryScene(Scene):
    def construct(self):
        shape_name = {{shape}}
        color_name = {{color}}
        label_text = {{label}}

        if color_name:
            color = color_name if color_name.startswith('#') else COLOR_MAP.get(color_name.lower(), YELLOW)
        else:
            color = YELLOW

        shapes = {
            "triangle": Polygon(LEFT * 2 + DOWN * 1.5, RIGHT * 2 + DOWN * 1.5, UP * 2),
            "square": Square(side_length=3),
            "circle": Circle(radius=1.8),
            "pentagon": RegularPolygon(5, radius=2),
            "hexagon": RegularPolygon(6, radius=2),
        }
        if shape_name not in shapes:
            shape_name = "circle"
        shape = shapes[shape_name].set_color(color).set_stroke(width=4)

        self.play(Create(shape), run_time=2)

        if label_text:
            label = _smart_text(label_text, font_size=50)
            self.play(Write(label))

        self.wait(2)
